import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Μη διαθέσιμες διασυνδέσεις και αβέβαιες πληρωμές","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/integration-problems.md","filePath":"el/help/integration-problems.md"}'),i={name:"el/help/integration-problems.md"};function n(l,a,s,h,p,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="μη-διαθεσιμες-διασυνδεσεις-και-αβεβαιες-πληρωμες" tabindex="-1">Μη διαθέσιμες διασυνδέσεις και αβέβαιες πληρωμές <a class="header-anchor" href="#μη-διαθεσιμες-διασυνδεσεις-και-αβεβαιες-πληρωμες" aria-label="Permalink to &quot;Μη διαθέσιμες διασυνδέσεις και αβέβαιες πληρωμές&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="γιατι-δεν-εχει-ρυθμιστει-μια-διασυνδεση" tabindex="-1">Γιατί δεν έχει ρυθμιστεί μια διασύνδεση; <a class="header-anchor" href="#γιατι-δεν-εχει-ρυθμιστει-μια-διασυνδεση" aria-label="Permalink to &quot;Γιατί δεν έχει ρυθμιστεί μια διασύνδεση;&quot;">​</a></h2><p>Η παρουσία προσαρμογέα στον κατάλογο δεν αποδεικνύει ζωντανή σύνδεση. Μπορεί να απαιτούνται πρόσβαση παρόχου, ρυθμίσεις και εγκεκριμένη ενεργοποίηση. Η δοκιμαστική προεπισκόπηση δεν μεταδίδει πραγματική κράτηση.</p><h2 id="ειναι-πραγματικο-ενα-δοκιμαστικο-μηνυμα-η-σημειο-gps" tabindex="-1">Είναι πραγματικό ένα δοκιμαστικό μήνυμα ή σημείο GPS; <a class="header-anchor" href="#ειναι-πραγματικο-ενα-δοκιμαστικο-μηνυμα-η-σημειο-gps" aria-label="Permalink to &quot;Είναι πραγματικό ένα δοκιμαστικό μήνυμα ή σημείο GPS;&quot;">​</a></h2><p>Όχι. Η αποστολή μηνυμάτων απαιτεί κατάλληλη συγκατάθεση και έγκριση παρόχου. Οι προσομοιωμένες συντεταγμένες δεν αποδεικνύουν θέση οχήματος. Η εκκρεμής συγκατάθεση δεν είναι θετική συγκατάθεση.</p><h2 id="τι-γινεται-αν-η-πληρωμη-ειναι-αβεβαιη" tabindex="-1">Τι γίνεται αν η πληρωμή είναι αβέβαιη; <a class="header-anchor" href="#τι-γινεται-αν-η-πληρωμη-ειναι-αβεβαιη" aria-label="Permalink to &quot;Τι γίνεται αν η πληρωμή είναι αβέβαιη;&quot;">​</a></h2><p>Εξετάστε το υπάρχον καθολικό και τους υποστηριζόμενους ελέγχους συμφωνίας ή ανάκτησης. Μην χρεώνετε ξανά λόγω απουσίας απάντησης. Προωθήστε το περιστατικό με κωδικούς παρόχου και κράτησης χωρίς ευαίσθητα στοιχεία. Μην περιλαμβάνετε στοιχεία κάρτας ή διαπιστευτήρια.</p><h2 id="που-ζητατε-βοηθεια" tabindex="-1">Πού ζητάτε βοήθεια <a class="header-anchor" href="#που-ζητατε-βοηθεια" aria-label="Permalink to &quot;Πού ζητάτε βοήθεια&quot;">​</a></h2><p>Ελέγξτε την ετοιμότητα και την εξουσιοδότηση με τον αρμόδιο διαχειριστή. Οι απενεργοποιημένες λειτουργίες παραμένουν κλειστές έως ξεχωριστή έγκριση.</p><p>Δείτε <a href="/el/integrations/activation-and-channels.html">Ετοιμότητα διασυνδέσεων</a>, <a href="/el/integrations/conversational-booking.html">Συνομιλιακές κρατήσεις</a>, <a href="/el/integrations/live-tracking.html">Παρακολούθηση</a> και <a href="/el/integrations/payment-providers.html">Πάροχοι πληρωμών</a>.</p>',11)])])}const _=e(i,[["render",n]]);export{m as __pageData,_ as default};
